sql.where:
p.status = 'PUBLISHED'
AND EXISTS (SELECT 1 FROM sr_blog_post_tag pt JOIN sr_blog_tag t ON t.id = pt.tag_id WHERE pt.post_id = p.id AND t.slug = #{tagSlug})
AND EXISTS (SELECT 1 FROM sr_blog_topic_post tp JOIN sr_blog_topic top ON top.id = tp.topic_id WHERE tp.post_id = p.id AND top.slug = #{topicSlug})
AND p.published_at >= #{publishedFrom}
AND p.published_at < #{publishedTo}

